.keycap{display:inline-block;font:8px 'DM Mono',monospace;border:1px solid #364153;background:#171e2b;color:#bbc4d0;border-radius:3px;padding:2px 4px;margin-right:3px}
.board-footer .keycap:nth-of-type(2){margin-left:5px}
.incoming-label{color:#7b879a}
.incoming-label.danger{color:#f18692}
.opponent-column{width:180px}
.enemy-frame{width:100%;aspect-ratio:1/2;opacity:.94}
.enemy-empty{position:absolute;inset:0;display:grid;place-content:center;text-align:center;background:rgba(10,14,24,.35);pointer-events:none}
.enemy-empty span{color:#6e5261;font-size:33px}
.enemy-empty small{font:7px 'DM Mono',monospace;color:#768093;letter-spacing:.7px;margin-top:5px}
.enemy-next-wrap{border:1px solid #283143;background:#111725;border-radius:5px;margin-top:12px;padding:7px 9px;height:82px}
.mini-label{display:flex;justify-content:space-between;color:#8995a8;font:8px 'DM Mono',monospace;letter-spacing:.5px}
.mini-label span{color:#da8292}
.enemy-next-wrap canvas{display:block;width:100%;height:54px}
.enemy-attack{margin-top:10px;text-align:center;border:1px solid #302837;background:#171520;border-radius:5px;padding:7px 3px;color:#8d879a;font:8px 'DM Mono',monospace}
.enemy-attack span{color:#eb8292}
.enemy-attack b{color:#f29ba5}
.arena-feed{margin-top:13px;height:32px;border:1px solid #293142;background:#111725;border-radius:5px;display:flex;align-items:center;padding:0 10px;gap:8px;color:#9aa5b7;font-size:9px}
.feed-icon{color:var(--gold);font-size:12px}
.arena-feed time{margin-left:auto;font:8px 'DM Mono',monospace;color:#657187}
.preview-card{border:1px solid #273143;background:#131a28;border-radius:6px;padding:10px 10px 4px;margin-bottom:11px}
.subtle{font:8px 'DM Mono',monospace;color:#738097;letter-spacing:0}
.preview-card canvas{display:block;width:100%;height:98px}
.hold-card canvas{height:75px}
.controls-heading{margin-bottom:10px}
.control-list{display:grid;gap:7px}
.control-list div{display:flex;align-items:center;gap:4px;color:#a4aec0;font-size:9px}
.control-list div span{margin-left:auto;color:#929daf}
.control-list kbd{font:8px 'DM Mono',monospace;background:#1a2130;border:1px solid #354054;color:#c2cad6;border-radius:3px;padding:3px 5px;min-width:20px;text-align:center}
.combat-log-head{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono',monospace;color:#a9b3c5;letter-spacing:.6px}
.log-live{color:#79d7a1;font-size:8px}
.log-live i{width:5px;height:5px;margin-right:4px}
.combat-log{height:79px;overflow:auto;margin-top:9px}
.log-entry{display:flex;gap:7px;align-items:flex-start;font-size:8px;color:#909caf;line-height:1.45;margin-bottom:7px}
.log-dot{width:5px;height:5px;border-radius:50%;background:#78859d;margin-top:3px;flex:none}
.log-dot.gold{background:#d8b166}
.log-dot.red{background:#e87888}
.log-dot.cyan{background:#63d5dc}
.pause-button{margin-top:11px;width:100%;height:32px;display:flex;align-items:center;justify-content:center;gap:7px;border:1px solid #344054;border-radius:5px;background:#171e2c;color:#aeb8c9;font:9px 'DM Mono',monospace;cursor:pointer}
.pause-button:disabled{opacity:.4;cursor:not-allowed}
.pause-button kbd{margin-left:auto;margin-right:8px;color:#808ca1;border:1px solid #354054;padding:2px 4px;border-radius:3px;font-size:8px}
