const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 const context=await browser.newContext({viewport:{width:1440,height:1000}});
 const page=await context.newPage();
 const errors=[];page.on('pageerror',e=>errors.push(String(e)));
 await page.goto('http://127.0.0.1:4173/index.html');
 await page.waitForSelector('#characterModal:not([hidden])');
 console.log('initial dialog',await page.locator('#characterModal').isVisible());
 await page.locator('#characterNameInput').fill('Test Warden');
 await page.locator('#characterForm button[type=submit]').click();
 console.log('points on creation',await page.locator('#attributePoints').textContent());
 for(let i=0;i<4;i++) await page.locator('[data-attribute="attack"]').click();
 for(let i=0;i<3;i++) await page.locator('[data-attribute="hp"]').click();
 for(let i=0;i<3;i++) await page.locator('[data-attribute="defense"]').click();
 console.log('allocation after spend',await page.locator('#attributePoints').textContent());
 await page.locator('#attributeDone').click();
 const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('runestack-player')));
 console.log('saved profile',saved);
 await page.locator('#startButton').click();
 await page.waitForTimeout(150);
 console.log('board sizes',await page.locator('canvas#playerBoard,canvas#enemyBoard').evaluateAll(cs=>cs.map(c=>[c.width,c.height])));
 console.log('active',await page.locator('#characterModal').isHidden(),await page.locator('#playerHpText').textContent(),'enemy mana hidden?',await page.locator('#enemyManaWrap').evaluate(e=>e.hidden));
 const before=await page.locator('#playerBoard').evaluate(c=>c.toDataURL());
 await page.keyboard.press('z'); await page.waitForTimeout(80);
 const after=await page.locator('#playerBoard').evaluate(c=>c.toDataURL());
 console.log('Z rotation changed board pixels',before!==after);
 await page.locator('[data-action="rotateccw"]').dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',isPrimary:true,button:0});
 await page.locator('[data-action="rotateccw"]').dispatchEvent('pointerup',{pointerId:1,pointerType:'touch',isPrimary:true,button:0});
 await page.waitForTimeout(60);
 console.log('touch rotation action exists and visible desktop',await page.locator('[data-action="rotateccw"]').isVisible());
 const desktop=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth}));
 console.log('desktop layout',desktop);
 await page.screenshot({path:'/tmp/opencode/runestack-verified-desktop.png',fullPage:true});
 await context.close();
 const mobileContext=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
 const mobile=await mobileContext.newPage();mobile.on('pageerror',e=>errors.push(String(e)));
 await mobile.goto('http://127.0.0.1:4173/index.html');
 await mobile.waitForSelector('#characterModal:not([hidden])');
 await mobile.locator('#characterNameInput').fill('Mobile Warden'); await mobile.locator('#characterForm button[type=submit]').click(); await mobile.locator('#attributeDone').click(); await mobile.locator('#startButton').click();
 console.log('mobile layout',await mobile.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth,touchVisible:getComputedStyle(document.querySelector('.touch-controls')).display!=='none',ccwVisible:!!(document.querySelector('[data-action="rotateccw"]').offsetWidth)})));
 await mobile.screenshot({path:'/tmp/opencode/runestack-verified-mobile.png',fullPage:true});
 console.log('page errors',errors);
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

