const TIER_COUNTS=[100,150,150,100,100,100,50,50,25,25,50];
const ENEMIES=[];
TIER_COUNTS.forEach((count,tierIndex)=>{
  const tier=tierIndex+1;
  for(let tierOffset=0;tierOffset<count;tierOffset++){
    const i=ENEMIES.length;
    const speciesIndex=i%SPECIES.length;
    const species=SPECIES[speciesIndex];
    const style=/Wolf|Bat|Lynx|Hound|Ape|Stag|Owl|Fox/.test(species)?'HUNTER':/Troll|Boar|Golem|Ram|Bear/.test(species)?'GUARDIAN':'MYSTIC';
    const spellCount=tier<4?(i%4===0?1:0):Math.min(5,1+Math.floor((tier-4)/2)+(i%4===0?1:0));
    const spellOffset=(i*3)%SPELLS.length;
    const spells=Array.from({length:spellCount},(_,n)=>SPELLS[(spellOffset+n*5)%SPELLS.length].id);
    const tierScale=1+(tier-1)*.018;
    ENEMIES.push({index:i,tier,style,name:`${species} ${EPITHETS[(Math.floor(i/SPECIES.length)+speciesIndex*3)%EPITHETS.length]}`,hp:Math.min(620,65+tier*7+tierOffset%9),attack:Math.max(3,Math.round((5+tier*0.5+(i%11)*.3)*tierScale)),defense:Math.min(75,4+Math.floor(tier*.42)+(i%9)),dropMs:Math.max(350,1180-(tier-1)*17),thinkMs:Math.max(240,800-(tier-1)*11),attackMs:Math.max(8000,27000-(tier-1)*360),spells,magic:spells.length>0,enemyManaMax:spells.length?Math.max(4,spellCount*3):0,hardDrop:Math.min(.86,.08+(tier-1)*.016),attackDamage:Math.min(40,5+Math.floor(tier*.62)),strategy:STRATEGIES[i%STRATEGIES.length],personality:PERSONALITIES[(i*3+Math.floor(i/20))%PERSONALITIES.length],voice:ANIMAL_VOICES[species]||null,holdChance:.08+(i%7)*.035});
  }
});

