function enemyPlacement(source=state.enemyPiece){
  if(!source)return null;
  let best=null;
  const foe=enemyInfo();
  for(let rotation=0,m=source.m;rotation<4;rotation++,m=rotateMatrix(m,1)){
    for(let x=0;x<=COLS-m[0].length;x++){
      const p={type:source.type,m,x,y:source.y};
      if(collides(state.enemy,p))continue;
      while(!collides(state.enemy,p,0,1))p.y++;
      const board=state.enemy.map(row=>row.slice());
      let topped=false;
      for(let y=0;y<m.length;y++)for(let xx=0;xx<m[y].length;xx++)if(m[y][xx]){
        const by=p.y+y;
        if(by<0)topped=true;
        else board[by][x+xx]=SHAPES[p.type].color;
      }
      if(topped)continue;
      const cleared=clearRows(board);
      const heights=[];
      let aggregateHeight=0,holes=0,deepHoles=0,bumpiness=0,maxHeight=0;
      for(let xx=0;xx<COLS;xx++){
        let top=ROWS;
        for(let yy=0;yy<ROWS;yy++)if(board[yy][xx]){top=yy;break}
        const h=ROWS-top;
        heights.push(h);aggregateHeight+=h;maxHeight=Math.max(maxHeight,h);
        let covered=0;
        for(let yy=top;yy<ROWS;yy++){
          if(board[yy][xx])covered++;
          else if(covered){holes++;deepHoles+=covered}
        }
      }
      for(let xx=0;xx<COLS-1;xx++)bumpiness+=Math.abs(heights[xx]-heights[xx+1]);
      let rowTransitions=0,columnTransitions=0,wellDepth=0;
      const topRow=Math.max(0,ROWS-maxHeight);
      for(let yy=topRow;yy<ROWS;yy++){
        let previous=true;
        for(let xx=0;xx<COLS;xx++){
          const filled=Boolean(board[yy][xx]);
          if(filled!==previous)rowTransitions++;
          previous=filled;
        }
        if(!previous)rowTransitions++;
      }
      for(let xx=0;xx<COLS;xx++){
        let previous=true;
        for(let yy=topRow;yy<ROWS;yy++){
          const filled=Boolean(board[yy][xx]);
          if(filled!==previous)columnTransitions++;
          previous=filled;
        }
        if(!previous)columnTransitions++;
        const left=xx===0?ROWS:heights[xx-1],right=xx===COLS-1?ROWS:heights[xx+1];
        const depth=Math.max(0,Math.min(left,right)-heights[xx]);
        wellDepth+=depth*(depth+1)/2;
      }
      const attack=cleared>=4?4:cleared===3?2:cleared===2?1:0;
      let score=cleared*1450+attack*380-aggregateHeight*5.2-holes*125-deepHoles*9-bumpiness*8-rowTransitions*3-columnTransitions*4-wellDepth*1.5-Math.max(0,maxHeight-12)**2*8;
      if(foe.style==='HUNTER')score+=cleared*380+attack*210-aggregateHeight*1.2;
      else if(foe.style==='GUARDIAN')score-=aggregateHeight*2+holes*65+bumpiness*8;
      else score+=Math.max(0,5-Math.abs(heights.reduce((a,b)=>a+b,0)/COLS-heights[4]))*10;
      switch(foe.strategy){
        case'TIDY':score-=holes*65+bumpiness*10+rowTransitions*2;break;
        case'EDGE':score-=Math.min(x,COLS-m[0].length-x)*12;break;
        case'CENTER_GAP':score+=Math.max(0,5-Math.abs(x+Math.floor(m[0].length/2)-5))*18;break;
        case'AGGRESSIVE':score+=cleared*420+attack*180;break;
        case'SAFE':score-=aggregateHeight*3+holes*90+Math.max(0,maxHeight-10)**2*7;break;
        case'WELL':score+=Math.min(18,wellDepth)*14;break;
        case'CHAOTIC':score+=(Math.random()-.5)*260;break;
      }
      if(foe.archetype==='TACTICIAN')score-=rowTransitions*2+columnTransitions*2;
      if(foe.archetype==='RAVAGER')score+=cleared*180+attack*100;
      if(!best||score>best.score)best={x,rotation,score};
    }
  }
  return best;
}

