function xpToNext(level){return 500+level*100}
const LINE_XP_RATE=.05,VICTORY_XP_RATE=1.5;
function expectedEnemyTier(level=profile?.level||1){return Math.min(11,Math.max(1,1+Math.floor(level/10)))}
function enemyStrengthGap(foe=enemyInfo()){return foe.tier-expectedEnemyTier()}
function enemyStrengthMultiplier(foe=enemyInfo()){const gap=enemyStrengthGap(foe);return Math.max(.55,Math.min(2.2,(1+gap*.15)*(foe.hard?1.1:1)))}
function enemyStrengthLabel(foe=enemyInfo()){const gap=enemyStrengthGap(foe);return gap>=2?'OVERWHELMING':gap===1?'STRONGER':gap===0?'EVEN':'WEAKER'}
function lineClearXp(cleared){const perLine=Math.max(1,Math.round(xpToNext(profile?.level||1)*LINE_XP_RATE));return perLine*cleared}
function victoryXp(foe=enemyInfo()){return Math.max(1,Math.round(xpToNext(profile?.level||1)*VICTORY_XP_RATE*enemyStrengthMultiplier(foe)))}

