  function auditEnemyRoster(){
    const rows=ENEMIES.map(foe=>{const p=enemyDifficultyProfile(foe);return {index:foe.index+1,name:foe.name,tier:foe.tier,hard:foe.hard,behavior:foe.behavior,strategy:foe.strategy,score:p.score,label:enemyDifficultyLabel(p.score),dropMs:foe.dropMs,thinkMs:foe.thinkMs,skill:Math.round(p.skill*100),hp:foe.hp,attack:foe.attack,defense:foe.defense,attackDamage:foe.attackDamage,holdChance:Math.round(foe.holdChance*100),spells:foe.spells.length,breakdown:p};});
    const tierAverages={};
    const tiers=TIER_COUNTS.map((count,idx)=>{
      const tier=idx+1,group=rows.filter(r=>r.tier===tier);
      const avg=Math.round(group.reduce((s,r)=>s+r.score,0)/group.length);
      tierAverages[tier]=avg;
      return {tier,count,avg,min:Math.min(...group.map(r=>r.score)),max:Math.max(...group.map(r=>r.score)),avgDropMs:Math.round(...),avgThinkMs:...,avgSkill:...};
    });
    const bands={};
    rows.forEach(r=>bands[r.label]=(bands[r.label]||0)+1);
    const outliers=rows.map(r=>({...r,delta:r.score-tierAverages[r.tier]})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));
    const checks=[
      {name:'900 enemies',pass:rows.length===900},
      {name:'Tier difficulty rises',pass:tiers.every((t,i)=>i===0||t.avg>=tiers[i-1].avg-1)},
      {name:'Tier 1 stays easy',pass:tiers[0].max<50},
      {name:'Champion tier is hardest',pass:tiers[10].avg===Math.max(...tiers.map(t=>t.avg))},
      {name:'No extreme tier outlier',pass:Math.abs(outliers[0]?.delta||0)<=18},
      {name:'Behavior variety',pass:new Set(rows.map(r=>r.behavior)).size===8}
    ];
    return {total:rows.length,tiers,bands,outliers:outliers.slice(0,12),checks,rows};
  }
